INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('illegale-pyrotechnik-wien-floridsdorf-343-boeller-sichergestellt','Illegale Pyrotechnik in Wien: 343 Böller in Floridsdorf','Die Wiener Polizei hat am Bahnhof Floridsdorf 343 verbotene Feuerwerkskörper sichergestellt – teils versteckt in einem Zug, teils bei zwei Jugendlichen. Die Polizei warnt vor Blitzknallsätzen.','Bei einer Schwerpunktaktion gegen **illegale Pyrotechnik in Wien** hat die Bereitschaftseinheit der Wiener Polizei am Sonntag am Bahnhof Floridsdorf insgesamt 343 Stück verbotener Feuerwerkskörper sichergestellt. Das teilte die Landespolizeidirektion Wien am Montag mit. Ein Teil der Ware lag versteckt in einem Zug, ein weiterer Teil wurde bei zwei Jugendlichen gefunden.

## Pyrotechnik in Zugstoilette versteckt

Die Beamtinnen und Beamten durchsuchten am 22. November einen Zug, der im Bahnhof Floridsdorf im 21. Bezirk hielt. In einer Toilette des Zuges stießen sie auf 96 Feuerwerkskörper der Kategorie F3 und 22 Stück der Kategorie F4. Ein Besitzer konnte dem Fund zunächst nicht zugeordnet werden.

Bei der weiteren Kontrolle wurden zwei Burschen im Alter von 12 und 14 Jahren angehalten. Bei ihnen fanden die Polizisten 100 Stück der Kategorie F2, die vermutlich Blitzknallsatz enthalten, sowie 35 Stück der Kategorie F4 mit verbotenem Blitzknallsatz. Der 14-Jährige hatte zusätzlich weitere 90 Stück F2-Pyrotechnik dabei.

## Airsoft-Pistole, Nothammer und Elektroschocker

Die Kontrolle brachte noch mehr zutage: Der 14-Jährige trug eine täuschend echt aussehende Airsoft-Pistole mit Schalldämpfer bei sich. Außerdem fanden die Beamten einen Nothammer, der mutmaßlich aus einem Waggon gestohlen worden war. Beide Jugendliche hatten zudem je ein Elektroschockgerät dabei, das als Taschenlampe getarnt war. Solche getarnten Geräte gelten in Österreich als verbotene Waffen.

Zusammengerechnet ergibt sich folgende Bilanz der Aktion:

- 96 Stück Kategorie F3 und 22 Stück Kategorie F4 aus der Zugstoilette
- 100 Stück F2 und 35 Stück F4 bei den beiden Jugendlichen
- 90 weitere Stück F2 beim 14-Jährigen
- zwei getarnte Elektroschocker, eine Airsoft-Pistole und ein Nothammer

## Polizei warnt vor illegaler Pyrotechnik in Wien

Wenige Wochen vor Silvester richtet die Wiener Polizei eine deutliche Warnung an die Bevölkerung. Feuerwerkskörper mit Blitzknallsatz bergen laut Polizei ein erhebliches Verletzungsrisiko und können schwerste Verletzungen verursachen. Die meisten Unfälle gehen demnach auf Sorglosigkeit, Unachtsamkeit oder missbräuchliche Verwendung zurück.

Als besonders gefährlich gilt verbotene Ware, die meist im Ausland gekauft wird. Solche Böller erfüllen keine Qualitäts- und Zulassungskriterien, ihre Wirkung ist kaum abschätzbar. Die Polizei rät daher dringend davon ab, solche Produkte zu kaufen oder zu verwenden.

## Was beim Kauf von Feuerwerk gilt

Pyrotechnische Artikel sind in Österreich in Kategorien eingeteilt, die nach Gefährlichkeit gestaffelt sind. Kleinfeuerwerk der Kategorie F1 ist ab 12 Jahren erlaubt, Kategorie F2 ab 16 Jahren. Für die Kategorie F3 gilt ein Mindestalter von 18 Jahren, Großfeuerwerk der Kategorie F4 dürfen nur Personen mit entsprechender Fachkenntnis verwenden. Raketen und Böller der Kategorie F2 dürfen im Ortsgebiet grundsätzlich nicht gezündet werden, Ausnahmen kann nur die Gemeinde per Verordnung festlegen.

Für Eltern bedeutet das: Kinder unter 16 Jahren dürfen weder Knallkörper der Kategorie F2 besitzen noch verwenden. Wer Feuerwerk kauft, sollte auf geprüfte Ware aus dem Fachhandel mit CE-Kennzeichnung achten.

Die Polizei kündigt in Wien regelmäßig Schwerpunktkontrollen an, etwa auch im Straßenverkehr, wie die [Verkehrskontrolle mit 567 Tempo-Anzeigen](/artikel/verkehrskontrolle-wien-schwerpunktaktion-raser-alkohol-oktober-2026) im Oktober zeigte. Erst vor wenigen Wochen stellten Ermittler in Favoriten zudem [rund 100 Akkus in einem fremden Kellerabteil](/artikel/diebesgut-wien-favoriten-kellerabteil-e-scooter-akkus) sicher. Die in Floridsdorf gefundenen Gegenstände wurden allesamt sichergestellt.','chronik','Wien','wien','news','Presseinfo Redaktion','/assets/img/artikel/illegale-pyrotechnik-wien-floridsdorf-343-boeller-sichergestellt.webp','Landespolizeidirektion Wien','https://www.polizei.gv.at/wien/presse/aussendungen/presse116a.html?prid=64676f734e4b494b334b553d&pro=0','published','2026-11-23T16:50:00.000Z','2026-11-23T16:50:00.000Z','Illegale Pyrotechnik Wien: 343 Böller entdeckt','Illegale Pyrotechnik in Wien: Polizei stellt am Bahnhof Floridsdorf 343 verbotene Böller sicher, auch bei zwei Jugendlichen. Was beim Feuerwerk gilt.','illegale Pyrotechnik Wien','["illegale Pyrotechnik Wien","Pyrotechnik","Böller Wien","Bahnhof Floridsdorf","Blitzknallsatz","Feuerwerk Silvester 2026","Pyrotechnik Kategorie F2 Alter","Polizei Wien Schwerpunktaktion","verbotene Böller Jugendliche"]','Illegale Pyrotechnik in Wien: sichergestellte Böller und Feuerwerkskörper','Police evidence table in a Vienna police station with a pile of confiscated colorful firework rockets and firecrackers in cardboard boxes, a uniformed officer''s gloved hands sorting them, cold winter evening light through a window, Austrian context, realistic documentary photo, no text, no logos, no readable signs','[{"q":"Wie viel illegale Pyrotechnik wurde in Wien-Floridsdorf sichergestellt?","a":"Die Polizei stellte am 22. November 2026 am Bahnhof Floridsdorf insgesamt 343 Stück verbotener Pyrotechnik sicher, teils in einer Zugstoilette, teils bei zwei Jugendlichen."},{"q":"Ab welchem Alter darf man in Österreich Feuerwerk kaufen?","a":"Kategorie F1 ab 12 Jahren, F2 ab 16 Jahren, F3 ab 18 Jahren. F4 ist Personen mit Fachkenntnis vorbehalten."},{"q":"Warum ist Blitzknallsatz so gefährlich?","a":"Laut Polizei bergen Böller mit Blitzknallsatz ein erhebliches Verletzungsrisiko und können schwerste Verletzungen verursachen, vor allem nicht zugelassene Ware aus dem Ausland."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
